WITH enriched AS (SELECT *, LEAD(balance) OVER (PARTITION BY account_type ORDER BY balance, id) next_balance, LAG(balance) OVER (PARTITION BY account_type ORDER BY balance, id) prev_balance, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY balance, id) row_seq FROM accounts), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, status ORDER BY next_balance NULLS LAST, id) AS latest_rank FROM enriched) t WHERE latest_rank = 1), ranked AS (SELECT id, customer_id, account_type, opened_date, status, next_balance, prev_balance, row_seq FROM deduped QUALIFY RANK() OVER (PARTITION BY account_type ORDER BY balance DESC NULLS LAST) = 1), ranked_accounts AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY next_balance DESC NULLS LAST, id) AS row_num FROM ranked) x WHERE row_num = 1), not_flagged AS (SELECT s.* FROM ranked_accounts s WHERE NOT EXISTS (SELECT 1 FROM transactions c WHERE c.account_id = s.id AND c.amount > 2500)) SELECT DATE_TRUNC('QUARTER', opened_date) AS quarter_start, COUNT(*) AS row_count, COUNT_IF(account_type = 'SAVINGS') AS savings_events, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM not_flagged GROUP BY CUBE (DATE_TRUNC('QUARTER', opened_date))
